#!/usr/bin/env bash
# Money Flow Command Center - installer voor Linux (Kali/Debian/Ubuntu).
# Gebruik:  bash install-money-flow.sh
# Installeert in ~/money-flow-command-center, maakt een eigen Python-omgeving,
# en start de app automatisch (ook na herstart) op poort 8501, bereikbaar in je thuisnetwerk.
set -euo pipefail
DIR="${MFCC_DIR:-$HOME/money-flow-command-center}"
PORT="${MFCC_PORT:-8501}"
echo "==> Installeren in $DIR (poort $PORT)"
if ! python3 -c "import venv, ensurepip" 2>/dev/null; then
  echo "==> python3-venv ontbreekt; installeren (sudo wachtwoord kan gevraagd worden)"
  sudo apt-get update -y && sudo apt-get install -y python3-venv python3-pip
fi
mkdir -p "$DIR"
sed '1,/^__PAYLOAD__$/d' "$0" | base64 -d | tar -xz -C "$DIR"
python3 -m venv "$DIR/.venv"
"$DIR/.venv/bin/pip" install --quiet --upgrade pip
"$DIR/.venv/bin/pip" install --quiet -r "$DIR/requirements.txt"
cat > "$DIR/start.sh" <<START
#!/usr/bin/env bash
cd "$DIR"
exec "$DIR/.venv/bin/streamlit" run app.py --server.headless true --server.address 0.0.0.0 --server.port $PORT
START
chmod +x "$DIR/start.sh"

# --- eigen app-venster: starter + icoon in het programmamenu en op het bureaublad ---
cat > "$DIR/money-flow.sh" <<LAUNCH
#!/usr/bin/env bash
# Opent Money Flow als eigen venster (zonder adresbalk). Start de app eerst als die niet draait.
URL="http://localhost:$PORT"
up() { (exec 3<>/dev/tcp/127.0.0.1/$PORT) 2>/dev/null; }
if ! up; then
  systemctl --user start money-flow.service 2>/dev/null || (nohup "$DIR/start.sh" > "$DIR/app.log" 2>&1 &)
  for i in \$(seq 1 80); do up && break; sleep 0.5; done
fi
for b in brave-browser brave chromium chromium-browser google-chrome google-chrome-stable microsoft-edge-stable; do
  if command -v "\$b" >/dev/null 2>&1; then
    exec "\$b" --app="\$URL" --class=MoneyFlow --user-data-dir="$DIR/.appwindow" --no-first-run --no-default-browser-check --window-size=1700,1050
  fi
done
exec xdg-open "\$URL"
LAUNCH
chmod +x "$DIR/money-flow.sh"
APPS="$HOME/.local/share/applications"
mkdir -p "$APPS"
cat > "$APPS/money-flow.desktop" <<DESK
[Desktop Entry]
Type=Application
Name=Money Flow
Comment=Money Flow Command Center
Exec=$DIR/money-flow.sh
Icon=$DIR/icon.svg
Terminal=false
Categories=Office;Finance;
StartupWMClass=MoneyFlow
DESK
chmod +x "$APPS/money-flow.desktop"
update-desktop-database "$APPS" 2>/dev/null || true
DESKTOP_DIR=$(xdg-user-dir DESKTOP 2>/dev/null || echo "$HOME/Desktop")
if [ -d "$DESKTOP_DIR" ]; then
  cp "$APPS/money-flow.desktop" "$DESKTOP_DIR/money-flow.desktop"
  chmod +x "$DESKTOP_DIR/money-flow.desktop"
  gio set "$DESKTOP_DIR/money-flow.desktop" metadata::trusted true 2>/dev/null || true
  gio set "$DESKTOP_DIR/money-flow.desktop" metadata::xfce-exe-checksum "$(sha256sum "$DESKTOP_DIR/money-flow.desktop" | awk '{print $1}')" 2>/dev/null || true
fi
IP=$(hostname -I 2>/dev/null | awk '{print $1}'); IP=${IP:-localhost}
if [ "${MFCC_NO_SERVICE:-0}" != "1" ] && command -v systemctl >/dev/null && systemctl --user show-environment >/dev/null 2>&1; then
  mkdir -p "$HOME/.config/systemd/user"
  cat > "$HOME/.config/systemd/user/money-flow.service" <<UNIT
[Unit]
Description=Money Flow Command Center
After=network-online.target

[Service]
ExecStart=$DIR/start.sh
Restart=on-failure
RestartSec=5

[Install]
WantedBy=default.target
UNIT
  systemctl --user daemon-reload
  systemctl --user enable money-flow.service
  systemctl --user restart money-flow.service
  loginctl enable-linger "$USER" 2>/dev/null || echo "   (tip: 'sudo loginctl enable-linger $USER' laat de app draaien zonder ingelogd te zijn)"
  echo "==> Dienst 'money-flow' draait. Beheer: systemctl --user status|restart|stop money-flow"
else
  pkill -f "$DIR/.venv/bin/streamlit" 2>/dev/null || true
  sleep 1
  nohup "$DIR/start.sh" > "$DIR/app.log" 2>&1 &
  echo "==> Gestart op de achtergrond (log: $DIR/app.log). Opnieuw starten: $DIR/start.sh"
fi
echo
echo "KLAAR. Start de app met het icoon 'Money Flow' (bureaublad of programmamenu), of: $DIR/money-flow.sh"
echo "       In een browser:        http://localhost:$PORT"
echo "       Op je telefoon (wifi): http://$IP:$PORT"
echo "       Handleiding:           $DIR/HANDLEIDING.pdf (ook in de app onder HANDLEIDING)"
exit 0
